//@ compile-flags: -O
macro_rules! return_tables {
    ($($route:literal => ($yes:literal, $no:literal)),* $(,)?) => {
        enum State { First(u8), Second(u8) }

        #[inline(never)]
        fn by_enum(route: u16, state: State) -> u16 {
            match route {
                $($route => match state {
                    State::First(_) => $yes,
                    State::Second(_) => $no,
                },)*
                _ => 999,
            }
        }

        #[inline(never)]
        fn by_integer(route: u16, value: u8) -> u16 {
            match route {
                $($route => match value { 0 => $yes, 1 => $no, _ => 999 },)*
                _ => 999,
            }
        }

        fn main() {
            let expected: &[(u16, u16)] = &[$(($yes, $no)),*];
            for (route, &(yes, no)) in expected.iter().enumerate() {
                let route = std::hint::black_box(route as u16);
                assert_eq!(by_enum(route, State::First(11)), yes);
                assert_eq!(by_enum(route, State::Second(23)), no);
                assert_eq!(by_integer(route, 0), yes);
                assert_eq!(by_integer(route, 1), no);
                assert_eq!(by_integer(route, 2), 999);
            }
            assert_eq!(by_enum(2000, State::First(0)), 999);
            assert_eq!(by_integer(2000, 0), 999);
        }
    };
}

